def transform(grid):
    # Repeat the marked 3x3 motif in each 5x3 tile region; preserve divider lines.
    out = [row[:] for row in grid]
    row_starts = [r for r in range(len(grid)) if any(v != 4 for v in grid[r]) and (r == 0 or all(v == 4 for v in grid[r-1]))]
    col_starts = [c for c in range(len(grid[0])) if any(grid[r][c] != 4 for r in range(len(grid))) and (c == 0 or all(grid[r][c-1] == 4 for r in range(len(grid))))]
    if not row_starts or not col_starts:
        return out
    # Pick the populated motif band, then copy its non-background cells into matching tiles.
    h = next((sum(1 for r in range(a,len(grid)) if all(grid[x][c] != 4 for x in [r] for c in range(len(grid[0])))) for a in row_starts), 0)
    # Bands are delimited by full-color-4 horizontal separators; columns similarly.
    rb=[]; a=0
    for r in range(len(grid)+1):
        if r==len(grid) or all(v==4 for v in grid[r]):
            if a<r: rb.append((a,r))
            a=r+1
    cb=[]; a=0
    for c in range(len(grid[0])+1):
        if c==len(grid[0]) or all(grid[r][c]==4 for r in range(len(grid))):
            if a<c: cb.append((a,c))
            a=c+1
    source = next(((a,b) for a,b in rb if any(v not in (1,4) for row in grid[a:b] for v in row)), rb[0])
    sr0,sr1=source
    for r0,r1 in rb:
        for c0,c1 in cb:
            for dr in range(min(r1-r0,sr1-sr0)):
                for dc in range(min(c1-c0,cb[0][1]-cb[0][0])):
                    v=grid[sr0+dr][cb[0][0]+dc]
                    if v not in (1,4): out[r0+dr][c0+dc]=v
    return out

